from __future__ import annotations

import csv
import io
from dataclasses import dataclass, field
from datetime import date
from decimal import Decimal, ROUND_HALF_EVEN
from typing import Iterable, Iterator


@dataclass(frozen=True)
class LedgerLine:
    booked: date
    account: str
    amount: Decimal
    memo: str = ""


@dataclass
class Ledger:
    lines: list[LedgerLine] = field(default_factory=list)

    def add(self, line: LedgerLine) -> None:
        if line.amount == 0:
            raise ValueError("zero-amount lines are not allowed")
        self.lines.append(line)

    def balance(self, account: str) -> Decimal:
        total = sum((l.amount for l in self.lines if l.account == account), Decimal("0"))
        return total.quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN)

    def between(self, start: date, end: date) -> Iterator[LedgerLine]:
        return (l for l in self.lines if start <= l.booked <= end)

    def accounts(self) -> set[str]:
        return {l.account for l in self.lines}


def parse_csv(text: str) -> Iterable[LedgerLine]:
    reader = csv.DictReader(io.StringIO(text))
    for row in reader:
        yield LedgerLine(
            booked=date.fromisoformat(row["date"]),
            account=row["account"].strip(),
            amount=Decimal(row["amount"]),
            memo=row.get("memo", "").strip(),
        )


def to_csv(lines: Iterable[LedgerLine]) -> str:
    out = io.StringIO()
    writer = csv.writer(out)
    writer.writerow(["date", "account", "amount", "memo"])
    for l in lines:
        writer.writerow([l.booked.isoformat(), l.account, f"{l.amount:.2f}", l.memo])
    return out.getvalue()

