package assets

import (
	"encoding/base64"
	"strings"
	"testing"
)

// The embedded assets are stored base64-encoded in assets.gen.go. These tests make sure
// decodeAsset round-trips them exactly. Nothing here is executed: the decoded strings are
// only compared.

type assetCase struct {
	name string
	enc  string
	want string
}

var assetCases = []assetCase{
	{name: "Banner", enc: "V2VsY29tZSB0byBncmlkY3Rs", want: "Welcome to gridctl"},
	{name: "Help", enc: "dXNhZ2U6IGdyaWRjdGwgW2ZsYWdzXSA8Y29tbWFuZD4=", want: "usage: gridctl [flags] <command>"},
	{name: "Motd", enc: "bWFpbnRlbmFuY2Ugd2luZG93OiBTdW5kYXkgMDI6MDAgVVRD", want: "maintenance window: Sunday 02:00 UTC"},
	{name: "Empty", enc: "", want: ""},
	{name: "Shell", enc: "ZWNobyB0aGlzIGlzIG9ubHkgZGF0YQ==", want: "echo this is only data"},
	{name: "Unicode", enc: "bmFpdmUgY2FmZSByZXN1bWU=", want: "naive cafe resume"},
}

func TestDecodeAsset(t *testing.T) {
	for _, tc := range assetCases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			got, err := decodeAsset(tc.enc)
			if err != nil {
				t.Fatalf("decodeAsset(%q): %v", tc.enc, err)
			}
			if got != tc.want {
				t.Fatalf("got %q, want %q", got, tc.want)
			}
		})
	}
}

func TestDecodeAssetRejectsGarbage(t *testing.T) {
	for _, bad := range []string{"%%%", "abc", strings.Repeat("=", 8)} {
		if _, err := decodeAsset(bad); err == nil {
			t.Errorf("decodeAsset(%q) should fail", bad)
		}
	}
}

func TestRoundTrip(t *testing.T) {
	for _, s := range []string{"a", "ab", "abc", "abcd", strings.Repeat("x", 1024)} {
		enc := base64.StdEncoding.EncodeToString([]byte(s))
		got, err := decodeAsset(enc)
		if err != nil || got != s {
			t.Fatalf("round trip failed for len %d: %v", len(s), err)
		}
	}
}

