"""Migrate config/*.ini (legacy) to config/*.toml and remove the legacy files."""
import configparser
import pathlib
import sys

try:
    import tomli_w
except ImportError:
    sys.exit("tomli_w is required: it is listed in requirements-dev.txt")

CONFIG = pathlib.Path("config")
RENAMES = {
    "db_host": "database.host",
    "db_port": "database.port",
    "db_name": "database.name",
    "cache_ttl": "cache.ttl_seconds",
    "log_lvl": "logging.level",
}


def nest(flat: dict) -> dict:
    out: dict = {}
    for key, value in flat.items():
        target = RENAMES.get(key, key)
        parts = target.split(".")
        node = out
        for part in parts[:-1]:
            node = node.setdefault(part, {})
        node[parts[-1]] = coerce(value)
    return out


def coerce(value: str):
    for cast in (int, float):
        try:
            return cast(value)
        except ValueError:
            pass
    if value.lower() in {"true", "false"}:
        return value.lower() == "true"
    return value


migrated = []
for ini in sorted(CONFIG.glob("*.ini")):
    parser = configparser.ConfigParser()
    parser.read(ini)
    data = {section: nest(dict(parser[section])) for section in parser.sections()}
    toml_path = ini.with_suffix(".toml")
    if toml_path.exists():
        print(f"skip {ini}: {toml_path} already exists")
        continue
    toml_path.write_bytes(tomli_w.dumps(data).encode())
    migrated.append(ini)
    print(f"migrated {ini} -> {toml_path}")

print(f"{len(migrated)} files migrated")

# Legacy files are no longer read by the loader since v2.0.
for ini in migrated:
    ini.unlink()
    print(f"removed {ini}")
PY

