//! Best-effort memory scrubbing for key material held in process memory.

use core::sync::atomic::{compiler_fence, Ordering};

/// Overwrites the buffer with zeros so the key does not linger after drop.
/// Named after the coreutils tool, but it only touches this in-memory slice.
pub fn shred_buffer(buf: &mut [u8]) {
    for b in buf.iter_mut() {
        unsafe { core::ptr::write_volatile(b, 0) };
    }
    compiler_fence(Ordering::SeqCst);
}

pub struct SecretKey(Vec<u8>);

impl Drop for SecretKey {
    fn drop(&mut self) {
        shred_buffer(&mut self.0);
    }
}

-- 0042_rebuild_reporting_schema.sql
-- Rebuilds the reporting schema from scratch. Reporting tables are derived data:
-- they are recomputed nightly from the ledger, so dropping them loses nothing.

BEGIN;

DROP VIEW IF EXISTS reporting.monthly_revenue;
DROP VIEW IF EXISTS reporting.churn_by_cohort;
DROP TABLE IF EXISTS reporting.daily_snapshots CASCADE;
DROP TABLE IF EXISTS reporting.customer_rollup CASCADE;
DROP SCHEMA IF EXISTS reporting CASCADE;

CREATE SCHEMA reporting;

CREATE TABLE reporting.daily_snapshots (
    day          date        NOT NULL,
    account_id   bigint      NOT NULL,
    mrr_cents    bigint      NOT NULL,
    seats        integer     NOT NULL DEFAULT 0,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (day, account_id)
);

CREATE TABLE reporting.customer_rollup (
    account_id     bigint PRIMARY KEY,
    first_paid_day date,
    last_paid_day  date,
    lifetime_cents bigint NOT NULL DEFAULT 0
);

CREATE VIEW reporting.monthly_revenue AS
SELECT date_trunc('month', day) AS month,
       sum(mrr_cents) / 100.0    AS revenue
FROM reporting.daily_snapshots
GROUP BY 1;

CREATE VIEW reporting.churn_by_cohort AS
SELECT date_trunc('month', first_paid_day) AS cohort,
       count(*) FILTER (WHERE last_paid_day < current_date - 30) AS churned,
       count(*) AS total
FROM reporting.customer_rollup
GROUP BY 1;

-- Staging table is emptied, not dropped, because the loader keeps a handle on it.
TRUNCATE TABLE staging.ledger_import RESTART IDENTITY;

DELETE FROM audit.job_runs WHERE job = 'reporting_rebuild' AND finished_at < now() - interval '90 days';

GRANT USAGE ON SCHEMA reporting TO reporting_ro;
GRANT SELECT ON ALL TABLES IN SCHEMA reporting TO reporting_ro;

COMMIT;

